'use client';
import { useEffect, useState } from 'react'; import Link from 'next/link'; import { useRouter } from 'next/navigation'; import type { AuthUser } from '@cdp/shared'; import { api, ApiClientError, type MemberOverview } from '@/lib/api'; import { Icon } from '@/components/icon';
export default function AccountPage(): React.JSX.Element { const router=useRouter(); const [user,setUser]=useState<AuthUser|null>(null),[overview,setOverview]=useState<MemberOverview|null>(null),[error,setError]=useState<string|null>(null),[notice,setNotice]=useState<string|null>(null),[busy,setBusy]=useState<string|null>(null); useEffect(()=>{let alive=true;api.me().then(async auth=>{if(!alive)return;setUser(auth.user);try{const data=await api.memberOverview();if(alive)setOverview(data);}catch(err){if(err instanceof ApiClientError&&err.status===401)router.replace('/login');else if(alive){setOverview({booking:null,camps:[]});setNotice('Camp registration is being prepared. Please check back shortly.');}}}).catch((err:unknown)=>{if(err instanceof ApiClientError&&err.status===401)router.replace('/login');else setError('Could not load your member space.');});return()=>{alive=false;};},[router]); async function book(campId:string,bedId:string){setBusy(bedId);try{await api.bookBed({campId,bedId});setNotice('Your bed request has been sent to the City Mega Church team for approval.');setOverview(await api.memberOverview());}catch(err){setError(err instanceof Error?err.message:'Could not reserve that bed.');}finally{setBusy(null);}} async function signOut(){setBusy('logout');try{await api.logout();router.replace('/login');}catch{setError('Could not sign out.');}finally{setBusy(null);}} const canAdmin=user?.permissions.includes('*')||user?.permissions.includes('reports.read_all'); return <section className="account-page"><div className="container"><p className="eyebrow">MEMBER SPACE</p><h1 className="page-account-title">Welcome back{user?`, ${user.fullName.split(' ')[0]}`:''}.</h1>{error&&<p className="alert">{error}</p>}{notice&&<p className="success-message">{notice}</p>}{user&&<div className="member-grid"><aside className="account-card member-profile"><p className="eyebrow">YOUR PROFILE</p><h2>{user.fullName}</h2><p>We’re glad you’re part of the City Mega Church community.</p><dl><dt>Email</dt><dd>{user.email}</dd><dt>Phone</dt><dd>{user.phone||'Not provided'}</dd></dl><div className="account-actions">{canAdmin&&<Link href="/admin" className="btn btn--primary">Admin dashboard <Icon name="arrow-up"/></Link>}<button className="btn btn--glass" disabled={busy==='logout'} onClick={()=>void signOut()}>Sign out <Icon name="logout"/></button></div></aside><main className="camp-panel"><p className="eyebrow">CAMP REGISTRATION</p><h2>Reserve your place.</h2>{overview?.booking?<div className="booking-status"><span className={`status status--${overview.booking.status}`}>{overview.booking.status}</span><h3>{overview.booking.campTitle}</h3><p>{overview.booking.room} · {overview.booking.bedLabel}</p></div>:overview?.camps.length?overview.camps.map(camp=><article className="camp-choice" key={camp.id}><h3>{camp.title}</h3><p>{camp.description}</p><div className="bed-grid">{camp.beds.map(bed=>{const available=bed.bookedCount<bed.capacity;return <button key={bed.id} className="bed-card" disabled={!available||busy!==null} onClick={()=>void book(camp.id,bed.id)}><span>{bed.room}</span><strong>{bed.label}</strong><small>{available?(busy===bed.id?'Reserving…':'Request this bed'):'Reserved'}</small></button>;})}</div></article>):<p>There is no open camp registration right now.</p>}</main></div>}</div></section>; }
